#!/usr/bin/env node
/**
 * Regenerate the Atlas migration that seeds cms.book_editions.
 *
 * The production Atlas apply path (infra/tools/run-db-migrations.sh --apply)
 * runs only "atlas migrate apply" against Aurora, with no Node and no seed
 * script, so seed-book-editions.ts / seedPlatform() never reach it. A
 * migration is the one artifact both the production runner and
 * pnpm db:migrate execute, so the book HTML is inserted as data in a
 * migration file, generated by this script from the same source files and
 * the same transforms seed-book-editions.ts applies.
 *
 * Run this and commit the regenerated migration whenever
 * packages/database/seed-assets/books/*.html changes:
 *
 *   node tools/scripts/gen-book-edition-migration.mjs
 *
 * Then, from packages/database:
 *
 *   atlas migrate hash --dir "file://atlas/migrations"
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..");
const DB_DIR = join(REPO_ROOT, "packages", "database");
const BOOKS_DIR = join(DB_DIR, "seed-assets", "books");
const MIGRATION_FILE = join(
  DB_DIR,
  "atlas",
  "migrations",
  "20260919013100_seed_book_editions.sql",
);

export const BOOK_SLUG = "deterministic-ai-coding-agents";
export const DOLLAR_TAG = "oxagen_book_html";

// Mirrors seed-book-editions.ts's stripLegacyGate: the field-manual source
// carries a client-side redirect script, so this drops it before storing.
// Access is enforced server-side instead.
export function stripLegacyGate(html) {
  return html.replace(
    /<script>[\s\S]*?ox_fm_unlocked[\s\S]*?<\/script>\s*/i,
    "",
  );
}

// Mirrors seed-book-editions.ts's rewriteFieldManualHref: the page-flip
// footer points at /field-manual, a path AWS S3/CloudFront has no object for.
export function rewriteFieldManualHref(html) {
  return html.replaceAll(
    'href="/field-manual"',
    'href="/read?e=field-manual"',
  );
}

export const EDITIONS = [
  {
    slug: "field-manual",
    file: "field-manual.html",
    format: "linear",
    title: "Engineering Deterministic AI Coding Agents \u2014 Field Manual",
    transform: stripLegacyGate,
  },
  {
    slug: "page-flip-reader",
    file: "page-flip-reader.html",
    format: "page-flip",
    title: "Engineering Deterministic AI Coding Agents \u2014 Reader",
    transform: rewriteFieldManualHref,
  },
];

function newPublicId() {
  return `bed_${randomUUID().replace(/-/g, "").slice(0, 22)}`;
}

/**
 * Render one INSERT statement for `edition`, dollar-quoting `html` so no
 * quote inside the book content can ever need escaping. Throws if `html`
 * happens to contain the dollar-quote tag itself.
 */
export function renderEditionInsert(edition, html, publicId = newPublicId()) {
  if (html.includes(`$${DOLLAR_TAG}$`)) {
    throw new Error(
      `dollar-quote tag "$${DOLLAR_TAG}$" collides with content for edition "${edition.slug}" ` +
        "-- pick a different DOLLAR_TAG",
    );
  }
  return `INSERT INTO "cms"."book_editions" ("public_id", "slug", "book_slug", "format", "title", "html", "published")
VALUES (
\t'${publicId}',
\t'${edition.slug}',
\t'${BOOK_SLUG}',
\t'${edition.format}',
\t'${edition.title.replace(/'/g, "''")}',
\t$${DOLLAR_TAG}$${html}$${DOLLAR_TAG}$,
\ttrue
)
ON CONFLICT ("slug") DO NOTHING;

`;
}

const HEADER = `-- Seed cms.book_editions so the production Atlas apply path actually leaves
-- the redeem route with real content instead of an empty table.
-- seed-book-editions.ts / seedPlatform() reach a dev or CI database through
-- pnpm db:migrate, but the production runner
-- (infra/tools/run-db-migrations.sh --apply) packages only atlas/ and
-- atlas.hcl and calls only "atlas migrate apply", with no Node and no seed
-- script. A migration is the one artifact both paths execute, so the
-- editions are inserted here.
--
-- Content is generated from packages/database/seed-assets/books/*.html with
-- the same transforms seed-book-editions.ts applies (stripLegacyGate,
-- rewriteFieldManualHref); regenerate with
-- tools/scripts/gen-book-edition-migration.mjs if a source file changes.
-- ON CONFLICT DO NOTHING: idempotent, and never overwrites a row the
-- app-level seed (or an editor) has already updated.

`;

/** Render the full migration file body for `editions`, each given its transformed html. */
export function renderMigration(editions) {
  let sql = HEADER;
  for (const { edition, html } of editions) {
    sql += renderEditionInsert(edition, html);
  }
  return sql;
}

function isDirectRun() {
  return process.argv[1] === fileURLToPath(import.meta.url);
}

if (isDirectRun()) {
  const rendered = EDITIONS.map((edition) => {
    const raw = readFileSync(join(BOOKS_DIR, edition.file), "utf8");
    const html = edition.transform ? edition.transform(raw) : raw;
    return { edition, html };
  });
  const sql = renderMigration(rendered);
  writeFileSync(MIGRATION_FILE, sql);
  process.stdout.write(
    `wrote ${MIGRATION_FILE} (${sql.length} bytes, ${EDITIONS.length} editions)\n`,
  );
}
